import { calcNumber } from '@/utils'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { SingleCoinImage } from '@cetus/ui-kit'
import Icon, { VariantType } from '@cetus/ui-kit/src/components/Icon'
import { SingleCoinImageProps } from '@cetus/ui-kit/src/components/SingleCoinImage'
import { d, textEllipses } from '@cetus/utils'
import { Center, Flex, FlexProps, Image, ImageProps, Text, TextProps } from '@chakra-ui/react'
import { ReactNode } from 'react'
import Block from './Block'
import CetusTooltip from './CetusTooltip'

type iconInfo = {
  xlinkHref: string
  svgW?: string
  svgH?: string
  variant?: VariantType
  isShowIcon?: boolean
  onClick?: (e: any) => void
}

type ImgInfo =
  | (ImageProps & {
      onClick?: (e: any) => void
    })
  | (Omit<SingleCoinImageProps, 'imageUrl'> & { src: string })

export type Tab<T = any> = {
  label: string
  key?: string
  value?: string
  beta?: boolean
  imgInfo?: ImgInfo
  beforeIcon?: iconInfo
  afterIcon?: iconInfo
  tooltip?: ReactNode
  num?: string | number
  isToken?: boolean
  comingSoon?: boolean
} & T

export interface SelectTabProps<T = any, K = any> extends FlexProps {
  type: 'outlineTab' | 'borderTab'
  currentTab: string | Tab<T> | K
  tabList: Tab<T>[]
  isActive?: (currentTab: string | Tab<T> | K, tab: Tab<T>) => boolean
  handleChangeTab: (item: Tab<T>) => void
  wrapStyle?: FlexProps
  itemStyle?: FlexProps
  selectTabItemTextStyle?: TextProps
}
export default function SelectTab<T, K>(props: SelectTabProps<T, K>) {
  const {
    type,
    tabList,
    currentTab,
    isActive,
    handleChangeTab,
    wrapStyle = { h: '60px', p: '8px' },
    itemStyle = { fontSize: '14px' },
    selectTabItemTextStyle,
    ...rest
  } = props

  const { isApp } = useWindowWidth()

  const _isActive = (tab: Tab<T>) => {
    return isActive ? isActive(currentTab, tab) : currentTab === (tab.key || tab.label)
  }
  return (
    <>
      {type === 'outlineTab' && (
        <Flex bg="bg_secondary" borderRadius="12px" border="1px solid" borderColor="border" {...wrapStyle}>
          {tabList?.map((tab, index) => {
            const isActive = _isActive(tab)
            return (
              <Flex
                position="relative"
                borderRadius="4px"
                align="center"
                justify="center"
                key={`${tab?.key || tab.label}#${index}`}
                cursor="pointer"
                bg={isActive ? 'card_bg' : 'none'}
                onClick={() => {
                  if (!tab.comingSoon) {
                    handleChangeTab(tab)
                  }
                }}
                _hover={{
                  p: {
                    color: isApp ? 'none' : 'primary'
                  }
                }}
                {...itemStyle}
              >
                {tab.imgInfo &&
                  (tab?.isToken ? <SingleCoinImage {...tab.imgInfo} imageUrl={tab.imgInfo.src} /> : <Image {...tab.imgInfo} src={tab.imgInfo.src} />)}
                {tab.beforeIcon &&
                  (tab?.tooltip ? (
                    <TooltipCon tooltip={tab.tooltip}>
                      <Icon {...tab.beforeIcon} isActive={isActive} />
                    </TooltipCon>
                  ) : (
                    <Icon {...tab.beforeIcon} isActive={isActive} />
                  ))}
                <Text
                  fontSize={itemStyle.fontSize}
                  whiteSpace="nowrap"
                  color={isActive ? 'primary' : 'primary_gray'}
                  _hover={{ color: isApp ? 'none' : 'primary' }}
                  {...selectTabItemTextStyle}
                >
                  {tab?.isToken ? textEllipses(tab.label, 10) : tab.label}
                </Text>
                {tab?.num !== '' && (tab?.num || Number(tab?.num) == 0) && (
                  <Block w="unset" lineHeight="1" ml="8px" p="2px 6px" borderRadius="8px" fontSize="12px" color="primary">
                    {tab?.num}
                  </Block>
                )}
                {tab?.comingSoon && (
                  <Text
                    bg="card_bg"
                    whiteSpace="nowrap"
                    color="primary"
                    borderRadius="4px"
                    padding="4px"
                    position="absolute"
                    top={{ base: '-12px', lg: '-12px' }}
                    left={{ base: '60px', lg: '100px' }}
                    fontSize={{ base: '10px', lg: '12px' }}
                  >
                    Coming Soon
                  </Text>
                )}
                {tab.afterIcon &&
                  (tab?.tooltip ? (
                    <TooltipCon tooltip={tab.tooltip}>
                      <Icon {...tab.afterIcon} isActive={isActive} />
                    </TooltipCon>
                  ) : (
                    <Icon {...tab.afterIcon} isActive={isActive} />
                  ))}
              </Flex>
            )
          })}
        </Flex>
      )}
      {type === 'borderTab' && (
        <Flex borderRadius="12px" bg="bg_secondary" border="1px solid" borderColor="border" {...wrapStyle}>
          {tabList?.map(tab => {
            return (
              <Flex
                position="relative"
                align="center"
                justify="center"
                key={tab?.key || tab.label}
                cursor="pointer"
                onClick={() => handleChangeTab(tab)}
                _hover={{
                  p: {
                    color: 'primary'
                  }
                }}
                {...itemStyle}
                {...rest}
              >
                {tab.imgInfo && <Image {...tab.imgInfo} src={tab.imgInfo.src} mr="8px" />}
                {tab.beforeIcon &&
                  (tab?.tooltip ? (
                    <TooltipCon tooltip={tab.tooltip}>
                      <Icon {...tab.beforeIcon} isActive={_isActive(tab)} />
                    </TooltipCon>
                  ) : (
                    <Icon {...tab.beforeIcon} isActive={_isActive(tab)} />
                  ))}
                <Text
                  color={_isActive(tab) ? 'primary' : 'primary_gray'}
                  fontSize={itemStyle.fontSize}
                  h={itemStyle.fontSize}
                  lineHeight={itemStyle.fontSize}
                  position="relative"
                  sx={Object.assign(
                    {
                      _hover: {
                        color: 'primary'
                      },
                      _before: _isActive(tab)
                        ? {
                            content: "''",
                            width: '20px',
                            height: '2px',
                            background: 'primary',
                            position: 'absolute',
                            left: 'calc(50% - 10px)',
                            bottom:
                              -d(calcNumber(wrapStyle.h as string | number))
                                .minus(calcNumber((itemStyle.fontSize || '14px') as string | number))
                                .div(2)
                                .toString() + 'px'
                          }
                        : {}
                    },
                    itemStyle?.sx || {}
                  )}
                >
                  {tab.label}
                </Text>
                {tab?.num !== '' && (tab?.num || Number(tab?.num) == 0) && (
                  <Block w="unset" lineHeight="1" ml="8px" p="2px 6px" borderRadius="8px" fontSize="12px" color="primary">
                    {tab?.num}
                  </Block>
                )}
                {tab?.comingSoon && (
                  <Text
                    bg="card_bg"
                    whiteSpace="nowrap"
                    color="primary"
                    borderRadius="4px"
                    padding="4px"
                    position="absolute"
                    top="-10px"
                    left="100px"
                    fontSize="12px"
                  >
                    Coming Soon
                  </Text>
                )}
                {tab.afterIcon &&
                  (tab?.tooltip ? (
                    <TooltipCon tooltip={tab.tooltip}>
                      <Icon {...tab.afterIcon} isActive={_isActive(tab)} />
                    </TooltipCon>
                  ) : (
                    <Icon {...tab.afterIcon} isActive={_isActive(tab)} />
                  ))}
                {tab?.beta && <Image src="/images/icon_beta@2x.png" position="absolute" right="-30px" top="10px" h="12px" />}
              </Flex>
            )
          })}
        </Flex>
      )}
    </>
  )
}

const TooltipCon = ({ children, tooltip }: { children: React.ReactNode; tooltip: React.ReactNode }) => {
  return (
    <CetusTooltip
      placement="bottom-end"
      tooltip={
        <Text fontSize="12px" lineHeight="20px">
          {tooltip}
        </Text>
      }
    >
      <Center>{children}</Center>
    </CetusTooltip>
  )
}
