import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { isColorValue } from '@cetus/utils'
import { Center, HTMLChakraProps } from '@chakra-ui/react'
import { useMemo, useState } from 'react'

export type VariantType = 'solid' | 'gray' | 'rectangle' | '' | 'error' | 'warning' | 'primary' | 'round'
export interface IconProps extends HTMLChakraProps<'div'> {
  xlinkHref: string
  svgW?: string
  svgH?: string
  boxW?: string
  boxH?: string
  iconCursor?: 'text' | 'pointer' | 'not-allowed' | 'default'
  svgHover?: string
  svgFill?: string
  variant?: VariantType
  onClick?: (e: any) => void
  isActive?: boolean
  activeColor?: string
  activeHoverColor?: string
}

/**
 *
 * @param props
 * variant
 *  空： 默认，不带背景，hover默认白色---cetus
 *  solid: 带背景，正方形
 *  gray: 不带背景，灰色系 hover白色
 *  primary: 不带背景，灰色hover主题色
 *  warning: warning icon
 *  error: error icon
 *  rectangle: 带背景，长方形
 *  round:带背景 圆形
 *
 * @returns
 */
export default function Icon(props: IconProps) {
  const {
    xlinkHref,
    fontSize,
    svgW,
    svgH,
    boxW,
    boxH,
    variant,
    svgHover,
    svgFill,
    onClick,
    iconCursor = 'pointer',
    isActive,
    activeColor,
    activeHoverColor,
    ...rest
  } = props

  const [clicked, setClicked] = useState(false)
  const { isApp } = useWindowWidth()

  const handleClick = (e: React.MouseEvent) => {
    if (isApp) {
      setClicked(true) // Only toggle clicked on mobile devices
    }
    if (onClick) onClick(e)
  }

  const style = useMemo(() => {
    const styles = {
      base: {
        box: {
          w: boxW || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC (non-mobile devices)
                  svg: {
                    fill: isActive && activeHoverColor ? activeHoverColor : svgHover || 'text_caption'
                  }
                }
              : undefined
        },
        svg: {
          fill:
            isActive && activeColor
              ? isColorValue(activeColor)
                ? activeColor
                : `var(--chakra-colors-${activeColor || 'text_paragraph'})`
              : svgFill && isColorValue(svgFill)
                ? svgFill
                : `var(--chakra-colors-${svgFill || 'text_paragraph'})`,
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      gray: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: 'text_caption'
                  }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      primary: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: 'primary'
                  }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      warning: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: 'primary_yellow'
                  }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-primary_yellow)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      error: {
        box: {
          w: boxH || fontSize || '20px',
          h: boxH || fontSize || '20px',
          bg: 'none',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: 'primary_red'
                  }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-primary_red)',
          width: svgW || fontSize || '20px',
          height: svgH || fontSize || '20px'
        }
      },
      solid: {
        box: {
          bg: 'checked_bg',
          w: boxW || fontSize || '24px',
          h: boxH || fontSize || '24px',
          borderRadius: '4px',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: isActive && activeHoverColor ? activeHoverColor : svgHover || 'text_caption'
                  }
                }
              : undefined
        },
        svg: {
          fill:
            isActive && activeColor
              ? isColorValue(activeColor)
                ? activeColor
                : `var(--chakra-colors-${activeColor || 'text_paragraph'})`
              : svgFill && isColorValue(svgFill)
                ? svgFill
                : `var(--chakra-colors-${svgFill || 'text_paragraph'})`,
          width: svgW || fontSize || '16px',
          height: svgH || fontSize || '16px'
        }
      },
      rectangle: {
        box: {
          bg: 'card_bg',
          w: boxW || fontSize || '28px',
          h: boxH || fontSize || '20px',
          borderRadius: '8px',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: 'primary'
                  }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-primary)',
          width: svgW || fontSize || '16px',
          height: svgH || fontSize || '16px'
        }
      },
      round: {
        box: {
          bg: 'card_bg',
          w: boxW || fontSize || '20px',
          h: boxH || fontSize || '20px',
          borderRadius: '50%',
          border: '1px',
          borderStyle: 'solid',
          borderColor: 'var(--chakra-colors-border)',
          background: 'var(--chakra-colors-bg_secondary)',
          _hover:
            !clicked && !isApp
              ? {
                  // Only apply hover on PC
                  svg: {
                    fill: 'text_caption'
                  }
                }
              : undefined
        },
        svg: {
          fill: 'var(--chakra-colors-text_paragraph)',
          width: svgW || fontSize || '16px',
          height: svgH || fontSize || '16px'
        }
      }
    }

    return !variant ? styles['base'] : styles[variant]
  }, [variant, svgW, svgH, boxW, boxH, fontSize, svgFill, svgHover, isActive, activeColor, activeHoverColor])

  return (
    <Center cursor={iconCursor} {...style.box} {...rest} onClick={handleClick}>
      <svg aria-hidden="true" {...style.svg}>
        <use xlinkHref={xlinkHref} />
      </svg>
    </Center>
  )
}
