import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import useGlobalStore from '@cetus/stores/src/global'
import { CommonTypeInfo, TransactionStatusType, WalletInfo, suiWalletList } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import {
  Grid,
  GridItem,
  HStack,
  Heading,
  Image,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalHeader,
  ModalOverlay,
  Text,
  VStack
} from '@chakra-ui/react'
import { MSafeWallet } from '@msafe/sui-wallet'
// import { useConnectWallet, useWallets } from '@mysten/dapp-kit'
import { useAccountStore } from '@cetus/stores'
import { useConnectWallet, useWallets } from '@mysten/dapp-kit'
import { getFullnodeUrl } from '@mysten/sui/client'
import { memo, useMemo } from 'react'
import { useGlobalToast } from '../../hooks'

type ConnectWalletModalProps = {
  isOpen: boolean
  onClose: () => void
}

function ConnectWalletModal(props: ConnectWalletModalProps) {
  const { isOpen, onClose } = props
  const supportWalletList = useWallets()
  const { isApp } = useWindowWidth()
  const { mutateAsync: connect } = useConnectWallet()

  const { customToast, successTsToast } = useGlobalToast()
  const { saveCurrentAccount, accountServiceNameObj, setAccountServiceNameObj, connectCallback, setConnectCallback } = useAccountStore()

  const { phantomInstance } = useGlobalStore()

  const walletArg: any = {
    wallet: (window as any).embed_phantom
  }

  const list: WalletInfo[] = useMemo(() => {
    if (!isApp) {
      return suiWalletList.filter((item: WalletInfo) => item.name !== 'Sui Wallet' && item.name !== 'xPortal') || []
    } else {
      return suiWalletList
    }
  }, [suiWalletList, isApp])

  const showInstallWalletToast = (wallet: WalletInfo) => {
    customToast(
      <VStack gap="8px" alignItems="start">
        <HStack>
          <Icon xlinkHref="#icon-icon_close" variant="error" />
          <Heading fontSize="14px" fontWeight="400" whiteSpace="nowrap" color="primary_red">
            Wallet Not Ready Error
          </Heading>
        </HStack>

        <HStack>
          <Text fontSize="14px" color="primary_gray" wordBreak="break-all">
            Please install
          </Text>
          <Text
            cursor="pointer"
            fontSize="14px"
            color="primary"
            wordBreak="break-all"
            onClick={() => {
              window.open(wallet.url, '_blank')
            }}
          >
            {wallet.name}
          </Text>
          <Text fontSize="14px" color="primary_gray" wordBreak="break-all">
            extension first
          </Text>
        </HStack>
      </VStack>
    )
  }

  const handleConnectWallet = async (wallet: WalletInfo) => {
    console.log('🚀 ~ file: ConnectWalletModal.tsx:30 ~ ConnectWalletModal ~ supportWalletList:', {
      supportWalletList,
      wallet
    })

    const isMsafeAndInMsafe = MSafeWallet?.inMSafeWallet() && wallet?.name === 'MSafe'
    // if ( && ) {
    //   connect(
    //     {
    //       wallet: new MSafeWallet('cetus', getFullnodeUrl('mainnet'), 'sui:mainnet'),
    //       silent: true
    //     },
    //     {
    //       onSuccess: data => {
    //         successTsToast({
    //           getShowInfo: (_: TransactionStatusType): CommonTypeInfo => {
    //             const info: CommonTypeInfo = {
    //               iconUrl: wallet.icon.startsWith('http') ? wallet.icon : `/images/wallet/${wallet.icon}.png`,
    //               toastTitleText: `Wallet Connected`
    //             }
    //             return info
    //           }
    //         })
    //         onClose()
    //         console.log('🚀 ~ file: ConnectWalletMode.tsx:61 ~ handleConnectWallet ~ onSuccess:', wallet.name, data)
    //       },
    //       onError: error => {
    //         //TODO 链接失败，需要提示---没有钱包提示去下载 用户拒绝的话不提示
    //         console.log('🚀 ~ file: ConnectWalletMode.tsx:65 ~ handleConnectWallet ~ onError:', error)
    //       }
    //     }
    //   )
    //   return
    // }

    const walletObj = supportWalletList.find(item =>
      wallet.walletName.includes('Slush') ? item.name.includes('Slush') : item.name === wallet.walletName
    )
    console.log('🚀 ~ handleConnectWal ~ wallet.walletName:', { supportWalletList, walletObj, phantomInstance })

    if (!isMsafeAndInMsafe && !walletObj) {
      showInstallWalletToast(wallet)
      return
    }

    const walletArg: any = isMsafeAndInMsafe
      ? {
          wallet: new MSafeWallet('cetus', getFullnodeUrl('mainnet'), 'sui:mainnet'),
          silent: true
        }
      : { wallet: walletObj }

    console.log('🚀 ~ handleConnectWal ~ walletArg sui:', walletObj, phantomInstance?.solana?.sui)

    try {
      if (phantomInstance) {
        if (walletObj?.name === 'Phantom') {
          phantomInstance.show()
        } else {
          phantomInstance.hide()
        }
      }
    } catch (error) {
      console.log('🚀 ~ handleConnectWal ~ error:', error)
    }

    await connect(walletArg, {
      onSuccess: (data, variables, context) => {
        successTsToast({
          getShowInfo: (_: TransactionStatusType): CommonTypeInfo => {
            const info: CommonTypeInfo = {
              iconUrl: wallet.icon.startsWith('http') ? wallet.icon : `/images/wallet/${wallet.icon}.png`,
              toastTitleText: `Wallet Connected`
            }
            return info
          }
        })
        console.log('🚀 ~ file: ConnectWalletMode.tsx:29 ~ handleConnectWallet ~ onSuccess:', {
          data,
          variables,
          context
        })

        onClose()
        connectCallback && connectCallback()
      },
      onError: (error, variables, context) => {
        //TODO 链接失败，需要提示---没有钱包提示去下载 用户拒绝的话不提示
        console.log('🚀 ~ file: ConnectWalletMode.tsx:29 ~ handleConnectWallet ~ onError:', {
          error,
          variables,
          context
        })
        if (String(error).includes('MetaMask not detected')) {
          showInstallWalletToast(wallet)
        }
      }
    })

    onClose()
    if (connectCallback) {
      setConnectCallback(null)
    }
  }
  return (
    <Modal autoFocus={false} returnFocusOnClose={false} isOpen={isOpen} onClose={onClose} isCentered>
      <ModalOverlay />
      <ModalContent minW={isApp ? '300px' : '552px'}>
        <ModalHeader>Connect a Wallet</ModalHeader>
        <ModalCloseButton />
        <ModalBody p="16px" textAlign="center">
          <VStack>
            <Grid templateColumns={isApp ? 'repeat(2, 1fr)' : 'repeat(3, 1fr)'} gap={13} w="100%">
              {list.map(item => (
                <GridItem key={item.name} colSpan={1}>
                  <HStack
                    p="0 12px"
                    h="60px"
                    bg="bg_six"
                    borderRadius="8px"
                    border="1px solid"
                    borderColor="border"
                    cursor="pointer"
                    _hover={{
                      p: { color: 'primary' }
                    }}
                    onClick={() => {
                      handleConnectWallet(item)
                    }}
                  >
                    <Image
                      src={item.icon.startsWith('http') ? item.icon : `/images/wallet/${item.icon}.png`}
                      alt="SVG Image"
                      boxSize={{ base: '28px', lg: '36px' }}
                      objectFit="cover"
                      borderRadius="8px"
                      loading="lazy"
                    />
                    <VStack align="flex-start" gap="4px">
                      {item.name == 'SuiMetaMaskSnap' ? (
                        <VStack align="flex-start" gap="0px">
                          <Text color="text_caption" textAlign="left">
                            Sui
                          </Text>
                          <Text textAlign="left" color="text_caption">
                            MetaMask
                          </Text>
                          <Text textAlign="left" color="text_caption">
                            Snap
                          </Text>
                        </VStack>
                      ) : (
                        <Text
                          lineHeight="16px"
                          textAlign="left"
                          color="text_caption"
                          whiteSpace="normal"
                          wordBreak="break-word"
                          overflowWrap="break-word"
                        >
                          {item.name}
                        </Text>
                      )}
                      {item.name == 'Binance' && (
                        <Text
                          fontWeight="500"
                          fontSize="10px"
                          p="2px 6px"
                          textAlign="center"
                          borderRadius="4px"
                          bg="primary_opacity.10"
                          color="primary"
                        >
                          Mobile
                        </Text>
                      )}
                    </VStack>
                  </HStack>
                </GridItem>
              ))}
            </Grid>
          </VStack>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}

export default memo(ConnectWalletModal)
