import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Token } from '@cetus/types'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { add0x, suiAddressLongToShort } from '@cetus/utils'
import { fixCoinType } from '@cetusprotocol/common-sdk'
import useTokenStore from 'packages/stores/src/token'

export default function useGetTokenSource() {
  const { importTokenList, liquidityTrustTokenList } = useTokenSelectStore()
  const { verifiedTokenMap } = useTokenStore()
  const getTokenSource = (tokensInfo: Token[]) => {
    const result: Token[] = []
    const tokenTypesSet = new Set([
      ...Array.from(verifiedTokenMap.values()).map(token => token.coin_type),
      ...importTokenList.map(token => token.coin_type)
    ])

    for (const tokenInfo of tokensInfo) {
      if (!tokenTypesSet.has(suiAddressLongToShort(add0x(tokenInfo.coin_type)))) {
        result.push(tokenInfo)
      }
    }

    return result
  }

  const getShowCoinTag = (coinType: string) => {
    if (fixCoinType(coinType) === fixCoinType(envConfigs.x_cetus_coin.coin_type)) {
      return false
    }
    const tokenTypesSet = Array.from(
      new Set([...Array.from(verifiedTokenMap.values()).map(token => token.coin_type), ...importTokenList.map(token => token.coin_type)])
    )

    if (tokenTypesSet?.length > 0 && tokenTypesSet?.includes(suiAddressLongToShort(add0x(coinType)))) {
      return false
    } else {
      return true
    }
  }

  const getTrustTokenSource = (tokensInfo: Token[]) => {
    const result: Token[] = []
    const tokenTypesSet = new Set([
      ...Array.from(verifiedTokenMap.values()).map(token => token.coin_type),
      ...importTokenList.map(token => token.coin_type),
      ...liquidityTrustTokenList.map(token => token.coin_type)
    ])
    for (const tokenInfo of tokensInfo) {
      if (!tokenTypesSet.has(suiAddressLongToShort(add0x(tokenInfo.coin_type || tokenInfo?.address || '')))) {
        result.push(tokenInfo)
      }
    }

    return result
  }

  return { getTokenSource, getTrustTokenSource, getShowCoinTag }
}
