import envConfigs from '@cetus/types/src/config/envConfigs'
import { CetusBurnSDK } from '@cetusprotocol/burn-sdk'
import { CetusDcaSDK } from '@cetusprotocol/dca-sdk'
import { CetusFarmsSDK } from '@cetusprotocol/farms-sdk'
import { CetusLimitOrderSDK } from '@cetusprotocol/limit-sdk'
import { CetusClmmSDK } from '@cetusprotocol/sui-clmm-sdk'
import { CetusVaultsSDK } from '@cetusprotocol/vaults-sdk'
import { CetusXcetusSDK } from '@cetusprotocol/xcetus-sdk'
import { CetusZapSDK } from '@cetusprotocol/zap-sdk'
import { getFastestRpc } from './rpcManager'

// 定义一个映射，用于动态创建 SDK 实例
export const sdkMap = {
  clmm: CetusClmmSDK,
  burn: CetusBurnSDK,
  dca: CetusDcaSDK,
  farms: CetusFarmsSDK,
  limit: CetusLimitOrderSDK,
  vaults: CetusVaultsSDK,
  xcetus: CetusXcetusSDK,
  zap: CetusZapSDK
}

type SdkType = keyof typeof sdkMap

export class SdkFactory {
  private rpcs: string[] = [] // 所有可用rpc
  private currentRpc: string | null = null // 当前rpc
  private instances: Map<SdkType, any> = new Map() // 缓存的 SDK 实例
  private account: string | null = null // 当前账户地址

  // 初始化工厂
  async initialize(rpc: string, rpcs?: string[]) {
    this.rpcs = rpcs || []
    this.currentRpc = rpcs && rpcs?.length > 0 ? await getFastestRpc(this.rpcs) : rpc
    // this.currentRpc = rpc
    console.log('currentRpc initialized:', this.currentRpc)
  }

  // 获取或创建 SDK 实例
  getSdk<T extends keyof typeof sdkMap>(sdkType: T): InstanceType<(typeof sdkMap)[T]> {
    if (!this.currentRpc) {
      throw new Error('SDK Factory not initialized. Call `initialize()` first.')
    }

    if (!this.instances.has(sdkType)) {
      // 动态创建 SDK 实例
      const SdkClass = sdkMap[sdkType]
      const sdkInstance = SdkClass.createSDK({ env: envConfigs.env, full_rpc_url: this.currentRpc })

      // 包装实例为 Proxy
      const proxyInstance = this.createProxy(sdkInstance, sdkType)
      if (proxyInstance && this.account) {
        proxyInstance.setSenderAddress(this.account)
      }
      this.instances.set(sdkType, proxyInstance)
    }

    const sdk = this.instances.get(sdkType)!

    return sdk
  }

  // 创建 Proxy 包装 SDK 实例
  private createProxy<T extends object>(sdkInstance: T, sdkType: SdkType): T {
    return new Proxy(sdkInstance, {
      get: (target, propKey: string, receiver) => {
        const originalMethod = Reflect.get(target, propKey, receiver)

        // 如果不是方法，直接返回
        if (typeof originalMethod !== 'function') {
          return originalMethod
        }

        // 包装方法，添加统一错误处理
        return async (...args: any[]) => {
          try {
            return await originalMethod.apply(target, args)
          } catch (error: any) {
            console.error(`Error in ${sdkType} SDK method "${propKey}":`, error)

            // 检测是否需要切换rpc
            if (error.message.includes('Network Error')) {
              console.warn('Network error detected. Switching to next rpc...')
              await this.switchRpc()
            }

            alert('发生错误，请稍后再试！')
            return error
          }
        }
      }
    })
  }

  // 切换到下一个最快rpc
  async switchRpc(rpc = '') {
    let newRpc = rpc
    if (!rpc) {
      newRpc = await getFastestRpc(this.rpcs)
    }
    this.currentRpc = newRpc

    // 更新所有已初始化的 SDK 实例
    this.instances.forEach(sdk => {
      if (sdk && typeof sdk.updateFullRpcUrl === 'function') {
        sdk.updateFullRpcUrl(newRpc)
      }
    })

    console.log('All SDKs updated to new fastest rpc:', newRpc)
  }

  // 设置账户地址
  setSenderAddress(address: string) {
    this.account = address
    this.instances.forEach(sdk => {
      if (sdk && typeof sdk.setSenderAddress === 'function') {
        sdk.setSenderAddress(address)
      }
    })
  }
}
